// Scan the stack for idle seats - swap for Okta System Log last-auth per app + vendor admin APIs
const THRESHOLD = 45;
const raw = [
  { user: 'Bea Ross', email: 'bea.ross@example.com', app: 'Figma', seatCostMonthly: 15, lastLoginDaysAgo: 92 },
  { user: 'Eli Moss', email: 'eli.moss@example.com', app: 'Zoom Pro', seatCostMonthly: 16, lastLoginDaysAgo: 130 },
  { user: 'Gio Ito', email: 'gio.ito@example.com', app: 'Miro', seatCostMonthly: 10, lastLoginDaysAgo: 210 }
];
return raw.filter(r => r.lastLoginDaysAgo > THRESHOLD).map(r => ({ json: r }));

// Aggregate responses. No reply after 7 days = flagged for the human policy call, never auto-revoked silently.
const keep = [], release = [], silent = [];
for (const item of $input.all()) {
  const j = item.json;
  const approved = j.data && typeof j.data.approved === 'boolean' ? j.data.approved : (typeof j.approved === 'boolean' ? j.approved : null);
  if (approved === true) keep.push(j);
  else if (approved === false) release.push(j);
  else silent.push(j);
}
const money = release.reduce((s, r) => s + r.seatCostMonthly, 0);
let body = 'License confirm-or-release results:\n\n';
body += '== Release now (' + release.length + ' seats, $' + money + '/mo back) ==\n' + release.map(r => '  ' + r.user + ' - ' + r.app).join('\n') + '\n\n';
body += '== Confirmed keep (' + keep.length + ') ==\n' + keep.map(r => '  ' + r.user + ' - ' + r.app).join('\n') + '\n\n';
body += '== No reply in 7 days (' + silent.length + ') ==\n' + silent.map(r => '  ' + r.user + ' - ' + r.app + ' (manager ping next, then release per policy)').join('\n');
body += '\n\nPrinciple: the user gets asked before the seat gets taken, and reclaim is reversible same-day.';
return [{ json: { subject: 'Confirm-or-release: ' + release.length + ' seats freed, ' + silent.length + ' pending', body } }];
